<fieldset><legend>Custom limits</legend><label class="check"><input type="radio" name="session_preset" value="custom" <?=$preset==='custom'?'checked':''?>><span>Use custom time and task limits</span></label>
<div class="volunteer-limits"><div><label for="volunteer-count">Task assignments</label><input id="volunteer-count" type="number" name="assignment_limit" min="1" max="20" value="<?=e($draft['assignment_limit']??3)?>"></div><div><label for="volunteer-minutes">Session minutes</label><input id="volunteer-minutes" type="number" name="minutes" min="5" max="240" value="<?=e($draft['minutes']??60)?>"></div></div></fieldset>
<fieldset><legend>Other causes or a specific question</legend><label class="check"><input type="radio" name="cause_choice" value="custom" <?=$choice==='custom'?'checked':''?>><span>Use the scope below</span></label>
<label for="volunteer-scope">Where would you like to help?</label><select id="volunteer-scope" name="scope_kind"><?php foreach(['all'=>'Help wherever needed','category'=>'A topic or category','research'=>'One research question'] as $value=>$label): ?><option value="<?=e($value)?>" <?=$scopeKind===$value?'selected':''?>><?=e($label)?></option><?php endforeach ?></select>
<div data-volunteer-scope="category"><label for="volunteer-category">Category</label><select id="volunteer-category" name="category_id"><option value="">Choose a category</option><?php foreach($categories as $category): ?><option value="<?=e($category['id'])?>" <?=(string)$categoryId===(string)$category['id']?'selected':''?>><?=e($category['name'])?></option><?php endforeach ?></select></div>
<div data-volunteer-scope="research"><label for="volunteer-research">Public research ID or readable URL name</label><input id="volunteer-research" name="research_id" maxlength="180" value="<?=e($draft['research_id']??'')?>"><p class="fine">Find it on the research page. Private and withdrawn questions cannot be selected.</p></div></fieldset>
<fieldset><legend>Worker configuration (advanced)</legend><p class="fine">The Research profile above limits eligible work. Use direct settings or a qualifying native launch record for the configured worker; disclose unavailable provider-effective readback. <a href="/volunteer/quick-start#phone-cloud">Phone / Dot instructions</a></p><p class="fine">Choose the configuration your worker can actually use. Unknown configured settings exclude tasks requiring them, including planning. A qualifying recorded launch does not authenticate effective inference. Actual submissions are checked again.</p>
<label for="volunteer-model">Exact worker model</label><select id="volunteer-model" name="model"><option value="">Not specified</option><?php foreach(wf_model_registry() as $id=>$model): ?><option value="<?=e($id)?>" <?=($draft['model']??'')===$id?'selected':''?>><?=e($model['label'])?></option><?php endforeach ?></select>
<label for="volunteer-effort">Actual reasoning effort</label><select id="volunteer-effort" name="reasoning"><option value="">Not specified</option><?php foreach(RQ_EFFORTS as $effort): ?><option value="<?=e($effort)?>" <?=($draft['reasoning']??'')===$effort?'selected':''?>><?=e(ucfirst($effort))?></option><?php endforeach ?></select>
<label for="volunteer-tool">AI tool or harness name</label><input id="volunteer-tool" name="tool" maxlength="100" value="<?=e($draft['tool']??'')?>" placeholder="For example: Codex or Claude Code">
<label for="volunteer-mode">Workflow mode</label><select id="volunteer-mode" name="workflow_mode"><option value="">No specific mode</option><option value="ultracode" <?=($draft['workflow_mode']??'')==='ultracode'?'selected':''?>>Ultracode — separate from effort</option></select><p class="fine">Enter names only. Never enter account credentials or API keys.</p></fieldset>
